import std.io
import std.string

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a = string.parseInt("12")
    match a {
        Some(v) => { io.println("got ${v}") }
        None => { io.println("a-none") }
    }
    let b = string.parseInt("9223372036854775807")
    match b {
        Some(v) => { io.println("max ${v}") }
        None => { io.println("b-none") }
    }
    let c = string.parseInt("12a")
    match c {
        Some(v) => { io.println("c-bad") }
        None => { io.println("c-none") }
    }
    return Ok(())
}
